import re
path = 'app/(portal)/crafting/crafting-workbench.tsx'
text = read(path)
pattern = re.compile(r'''\{craftedReveal\.item\.image_url \? \(\s*// eslint-disable-next-line @next/next/no-img-element\s*<img\s*src=\{\s*craftedReveal\.item\s*\.image_url\s*\}\s*alt=""\s*className="h-full w-full object-contain"\s*/>\s*\) : \(\s*<span\s*className="font-serif text-5xl"\s*style=\{\{\s*color:\s*craftingAccent,\s*\}\}\s*>\s*◇\s*</span>\s*\)\}''', re.S)
replacement = '''<ItemImageFrame
                        src={craftedReveal.item.image_url}
                        quality={craftedReveal.item.quality}
                        className="h-full w-full"
                        badgeSize="md"
                        imageClassName="h-full w-full object-contain"
                      />'''
text, count = pattern.subn(replacement, text, count=1)
if count != 1:
    raise SystemExit(f'Craft Complete reveal image: expected exactly 1 match, found {count}. Make sure your working tree is based on {BASE}.')
write(path, text)

